using System.Data.Common;
using Microsoft.AspNetCore.Mvc;
using Microsoft.AspNetCore.Mvc.RazorPages;
using Microsoft.Extensions.Configuration;

namespace Migrated.Pages;

public sealed class CheckoutModel(DbDataSource dataSource, IConfiguration configuration) : PageModel
{
    [BindProperty]
    public string? Address { get; set; }

    public async Task<IActionResult> OnGetAsync(CancellationToken cancellationToken)
    {
        return Page();
    }

    public async Task<IActionResult> OnPostAsync(string address, CancellationToken cancellationToken)
    {
        if (string.IsNullOrEmpty(address))
        {
            ModelState.AddModelError(nameof(Address), "Address is required.");
            return Page();
        }

        var connectionString = configuration.GetConnectionString("ShopDb");
        if (string.IsNullOrEmpty(connectionString))
        {
            ModelState.AddModelError("ConnectionString", "Connection string is missing.");
            return Page();
        }

        await using var connection = new SqlConnection(connectionString);
        await connection.OpenAsync(cancellationToken);

        var insert = new SqlCommand(
            "INSERT INTO Orders (CustomerId, ShippingAddress) VALUES (@CustomerId, @ShippingAddress); SELECT SCOPE_IDENTITY();",
            connection);

        var parameterCustomerId = insert.CreateParameter();
        parameterCustomerId.ParameterName = "@CustomerId";
        parameterCustomerId.Value = Session["CustomerId"]?.ToString();
        insert.Parameters.Add(parameterCustomerId);

        var parameterShippingAddress = insert.CreateParameter();
        parameterShippingAddress.ParameterName = "@ShippingAddress";
        parameterShippingAddress.Value = address;
        insert.Parameters.Add(parameterShippingAddress);

        int orderId = Convert.ToInt32(await insert.ExecuteScalarAsync(cancellationToken));

        foreach (var item in Session["Cart"] as Dictionary<int, int>)
        {
            var update = new SqlCommand(
                "UPDATE Inventory SET Stock = Stock - @Quantity WHERE ProductId = @ProductId",
                connection);

            var parameterProductId = update.CreateParameter();
            parameterProductId.ParameterName = "@ProductId";
            parameterProductId.Value = item.Key;
