using System.Data.Common;
using Microsoft.AspNetCore.Mvc;
using Microsoft.AspNetCore.Mvc.RazorPages;

namespace Migrated.Pages;

public sealed class CheckoutModel(DbDataSource dataSource) : PageModel
{
    [BindProperty]
    public string? Address { get; set; }

    [BindProperty]
    public Dictionary<int, int> Cart { get; set; } = new Dictionary<int, int>();

    public async Task<IActionResult> OnGetAsync(CancellationToken cancellationToken)
    {
        Address = await GetAddressAsync(cancellationToken);
        return Page();
    }

    public async Task<IActionResult> OnPostAsync(CancellationToken cancellationToken)
    {
        if (!ModelState.IsValid) return Page();

        var orderId = await CreateOrderAsync(cancellationToken);

        Session.Remove("Cart");
        return RedirectToPage("Confirmation", new { orderId = orderId });
    }

    private async Task<string> GetAddressAsync(CancellationToken cancellationToken)
    {
        var address = Request.Form["ShippingAddress"];
        return address;
    }

    private async Task<int> CreateOrderAsync(CancellationToken cancellationToken)
    {
        var cart = Session["Cart"] as Dictionary<int, int> ?? new Dictionary<int, int>();
        if (cart.Count == 0)
        {
            throw new InvalidOperationException("Your cart is empty.");
        }

        var connectionString = Configuration.GetConnectionString("ShopDb") ?? throw new InvalidOperationException("ShopDb connection string not found.");

        await using var connection = new SqlConnection(connectionString);
        await connection.OpenAsync(cancellationToken);

        var orderId = await InsertOrderAsync(connection, cancellationToken);

        foreach (var item in cart)
        {
            await UpdateInventoryAsync(connection, item.Key, item.Value, cancellationToken);
        }

        return orderId;
    }

    private async Task<int> InsertOrderAsync(SqlConnection connection, CancellationToken cancellationToken)
    {
        var insert = new CommandDefinition(
            "INSERT INTO Orders (CustomerId, ShippingAddress) VALUES (@CustomerId, @ShippingAddress); SELECT SCOPE_IDENTITY();",
            new { CustomerId = Session["CustomerId"]?.ToString() ?? throw new InvalidOperationException("Customer ID not found."), ShippingAddress = Address },
            cancellationToken: cancellationToken);
        return (int)await insert.ExecuteScalarAsync(cancellationToken);
    }

    private async Task UpdateInventoryAsync(SqlConnection connection, int productId, int quantity, CancellationToken cancellationToken)
    {
        var update = new CommandDefinition(
            "UPDATE Inventory SET Stock = Stock - @Quantity WHERE ProductId = @ProductId",
            new { ProductId = productId, Quantity = quantity },
            cancellationToken: cancellationToken);
        await update.ExecuteNonQueryAsync(cancellationToken);
    }
}

