namespace Migrated.Pages;

public sealed class CheckoutModel(DbDataSource dataSource, IConfiguration configuration) : PageModel
{
    [BindProperty]
    public int? CartId { get; set; }

    [BindProperty]
    public string ShippingAddress { get; set; } = default!;

    public async Task<IActionResult> OnGetAsync(int cartId, CancellationToken cancellationToken)
    {
        CartId = cartId;
        return Page();
    }

    public async Task<IActionResult> OnPostAsync(CancellationToken cancellationToken)
    {
        var cart = await GetCartAsync(CartId, cancellationToken);
        if (cart == null || cart.Count == 0)
        {
            ErrorLabel.Text = "Your cart is empty.";
            return Page();
        }

        var address = ShippingAddress;
        var connectionString = configuration.GetConnectionString("ShopDb");

        await using var connection = new SqlConnection(connectionString);
        await connection.OpenAsync(cancellationToken);

        var orderId = await InsertOrderAsync(connection, cartId, address, cancellationToken);

        foreach (var item in cart)
        {
            await UpdateInventoryAsync(connection, item.Key, item.Value, cancellationToken);
        }

        Session.Remove("Cart");
        return RedirectToPage("Confirmation", new { orderId = orderId });
    }

    private async Task<IReadOnlyDictionary<int, int>> GetCartAsync(int cartId, CancellationToken cancellationToken)
    {
        await using var command = dataSource.CreateCommand("SELECT ProductId, Quantity FROM CartItems WHERE CartId = @cartId");
        var parameter = command.CreateParameter();
        parameter.ParameterName = "@cartId";
        parameter.Value = cartId;
        command.Parameters.Add(parameter);
        var cartItems = await command.ExecuteReaderAsync(cancellationToken);
        var cart = new Dictionary<int, int>();
        while (await cartItems.ReadAsync(cancellationToken))
        {
            cart[cartItems.GetInt32(0)] = cartItems.GetInt32(1);
        }
        return cart;
    }

    private async Task<int> InsertOrderAsync(SqlConnection connection, int cartId, string address, CancellationToken cancellationToken)
    {
        var insert = new SqlCommand(
            "INSERT INTO Orders (CustomerId, ShippingAddress) VALUES (@cartId, @address); SELECT SCOPE_IDENTITY();",
            connection);
        var parameter = insert.CreateParameter();
        parameter.ParameterName = "@cartId";
        parameter.Value = cartId;
        insert.Parameters.Add(parameter);
        parameter = insert.CreateParameter();
        parameter.ParameterName = "@address";
        parameter.Value = address;
        insert.Parameters.Add(parameter);
        return (int)(await insert.ExecuteScalarAsync(cancellationToken));
    }

    private async Task UpdateInventoryAsync(SqlConnection connection, int productId, int quantity, CancellationToken cancellationToken)
    {
        var update = new SqlCommand(
            "UPDATE Inventory SET Stock = Stock - @quantity WHERE ProductId = @productId",
            connection);
        var parameter = update.CreateParameter();
        parameter.ParameterName = "@productId";
        parameter.Value = productId;
        update.Parameters.Add(parameter);
        parameter = update.CreateParameter();
        parameter.ParameterName = "@quantity";
        parameter.Value = quantity;
        await update.ExecuteNonQueryAsync(cancellationToken);
    }
}

